import { chromium } from "playwright";
import { writeFileSync } from "node:fs";

const OUT = "/home/mvhenten/development/.tmp/stallion-now";
const POLL_URL = "http://127.0.0.1:5173/b/default";
const PAGE_URL = "http://100.104.44.51:5173/b/default";

function sleep(ms) {
  const sab = new SharedArrayBuffer(4);
  const ia = new Int32Array(sab);
  Atomics.wait(ia, 0, 0, ms);
}

async function waitForServer() {
  const deadline = Date.now() + 60000;
  while (Date.now() < deadline) {
    try {
      const res = await fetch(POLL_URL);
      if (res.status === 200) return true;
    } catch {
      // not up yet
    }
    sleep(1000);
  }
  throw new Error("server did not answer 200 within 60s");
}

async function shootScheme(browser, scheme) {
  const context = await browser.newContext({
    viewport: { width: 1200, height: 1920 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    colorScheme: scheme,
  });

  const page = await context.newPage();

  const consoleLines = [];
  page.on("console", (msg) => {
    const type = msg.type();
    if (type === "error" || type === "warning") {
      consoleLines.push(`[console.${type}] ${msg.text()}`);
    }
  });
  page.on("pageerror", (err) => {
    consoleLines.push(`[pageerror] ${err.message}`);
  });
  page.on("requestfailed", (req) => {
    consoleLines.push(
      `[requestfailed] ${req.method()} ${req.url()} ${req.failure()?.errorText ?? ""}`
    );
  });

  await page.goto(PAGE_URL);
  sleep(3000);
  await page.screenshot({ path: `${OUT}/01-${scheme}-loaded.png` });

  const cdp = await context.newCDPSession(page);

  const makeTouch = (x, y) => ({
    x,
    y,
    radiusX: 1,
    radiusY: 1,
    rotationAngle: 0,
    force: 1,
    id: 1,
  });

  await cdp.send("Input.dispatchTouchEvent", {
    type: "touchStart",
    touchPoints: [makeTouch(300, 600)],
  });

  const steps = 10;
  for (let i = 1; i <= steps; i++) {
    const x = 300 + ((700 - 300) * i) / steps;
    const y = 600 + ((900 - 600) * i) / steps;
    await cdp.send("Input.dispatchTouchEvent", {
      type: "touchMove",
      touchPoints: [makeTouch(x, y)],
    });
    sleep(30);
  }

  await cdp.send("Input.dispatchTouchEvent", {
    type: "touchEnd",
    touchPoints: [],
  });

  sleep(1000);
  await page.screenshot({ path: `${OUT}/02-${scheme}-after-stroke.png` });

  await page.reload();
  sleep(3000);
  await page.screenshot({ path: `${OUT}/03-${scheme}-after-reload.png` });

  const bodyText = await page.evaluate(() => document.body.innerText);
  writeFileSync(`${OUT}/text-${scheme}.txt`, bodyText, "utf8");
  writeFileSync(`${OUT}/console-${scheme}.txt`, consoleLines.join("\n"), "utf8");

  await context.close();
}

async function main() {
  await waitForServer();
  const browser = await chromium.launch();
  try {
    await shootScheme(browser, "light");
    await shootScheme(browser, "dark");
  } finally {
    await browser.close();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

